class Solution:
    def reverseBits(self, n: int) -> int:
        res = 0
        for i in range(32):
            bit = (n >> i) & 1
            res |= (bit << (31 - i))
        return res

reference_solution.javascript:
function reverseBits(n) {
    let res = 0;
    for (let i = 0; i < 32; i++) {
        const bit = (n >>> i) & 1;
        res = (res | (bit << (31 - i))) >>> 0;
    }
    return res;
}
